mapper.select:


     and A.supplier_id = #{brtSupplierVo.supplierId}
     and A.supplier_name = #{brtSupplierVo.supplierName}
     and A.supplier_no = #{brtSupplierVo.supplierNo}
     and A.supplier_type = #{brtSupplierVo.supplierType}
     and A.linkman = #{brtSupplierVo.linkman}
     and A.phone = #{brtSupplierVo.phone}
     and A.action = #{brtSupplierVo.action}
     and A.payment_type = #{brtSupplierVo.paymentType}
     and A.payer = #{brtSupplierVo.payer}
     and A.account = #{brtSupplierVo.account}

        and (A.supplier_name like concat('%', #{brtSupplierVo.keyWords}, '%') or A.supplier_no like concat('%', #{brtSupplierVo.keyWords}, '%'))




                and date_format(A.create_time,'%y%m%d') = date_format(now(),'%y%m%d')


                and DATE(A.create_time) = CURDATE() - INTERVAL 1 DAY


                and date_format(A.create_time,'%y%m') = date_format(now(),'%y%m')


                and QUARTER(A.create_time) = QUARTER(CURDATE()) and YEAR(A.create_time) = YEAR(CURDATE())


                and YEAR(A.create_time) = YEAR(CURDATE())




        and date_format(A.create_time,'%y%m%d') between date_format(#{brtSupplierVo.createTimes[0]},'%y%m%d') and date_format(#{brtSupplierVo.createTimes[1]},'%y%m%d')


        and supplier_id in

            #{item}



order by A.create_time desc
